import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { promisify } from "node:util";
import type { HookCallback, PreToolUseHookInput, StopHookInput } from "@anthropic-ai/claude-agent-sdk";

const PROTECTED = ["test/", ".github/workflows/"];
const NEVER_RUN = /\b(terraform|tofu)\b.*\b(apply|destroy)\b|gh\s+workflow\s+run/;

const deny = (reason: string) => ({
  hookSpecificOutput: { hookEventName: "PreToolUse" as const, permissionDecision: "deny" as const, permissionDecisionReason: reason },
});

export const guardWalls: HookCallback = async (input) => {
  const { tool_name, tool_input } = input as PreToolUseHookInput;
  const args = tool_input as { file_path?: string; command?: string };
  if (args.file_path && PROTECTED.some((p) => args.file_path!.includes(p))) {
    return deny("That file is one of the checks your work is judged by. Change the code, or add a new test file.");
  }
  if (tool_name === "Bash" && args.command && NEVER_RUN.test(args.command)) {
    return deny("Agents never apply, destroy or dispatch. Write a note for a person instead.");
  }
  return {};
};

import { query } from "@anthropic-ai/claude-agent-sdk";
import { guardWalls, proofBeforeDone, typecheckAfterEdit } from "./hooks.js";

for await (const msg of query({
  prompt: "The test in test/cart.test.ts fails. Make it pass.",
  options: {
    model: "claude-haiku-5-5",
    settingSources: [],
    allowedTools: ["Read", "Glob", "Grep", "Edit", "Write", "Bash"],
    permissionMode: "dontAsk",
    hooks: {
      PreToolUse: [{ matcher: "Edit|Write|Bash", hooks: [guardWalls] }],
      PostToolUse: [{ matcher: "Edit|Write", hooks: [typecheckAfterEdit] }],
      Stop: [{ hooks: [proofBeforeDone] }],
    },
  },
})) {
  if (msg.type === "result" && msg.subtype === "success") console.log("said:", msg.result);
}

export const proofBeforeDone: HookCallback = async (input) => {
  if ((input as StopHookInput).stop_hook_active) return {};
  if (existsSync("proof/tests-passed.txt")) return {};
  return { decision: "block", reason: "Before you stop, run the tests and save their output to proof/tests-passed.txt." };
};

