import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { HookCallback, StopHookInput } from "@anthropic-ai/claude-agent-sdk";

const hashAll = (dir: string): Record<string, string> =>
  Object.fromEntries(
    readdirSync(dir, { recursive: true, withFileTypes: true })
      .filter((entry) => entry.isFile())
      .map((entry) => join(entry.parentPath, entry.name))
      .map((path) => [path, createHash("sha256").update(readFileSync(path)).digest("hex")]),
  );

export const lockChecks = (dir: string): HookCallback => {
  const before = hashAll(dir);
  return async (input) => {
    if ((input as StopHookInput).stop_hook_active) return {};
    const now = hashAll(dir);
    const changed = Object.keys(before).filter((path) => now[path] !== before[path]);
    if (changed.length === 0) return {};
    return { decision: "block", reason: `These locked checks changed: ${changed.join(", ")}. Restore them and fix the code instead.` };
  };
};

// test/lock.test.ts
import assert from "node:assert/strict";
import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import type { StopHookInput } from "@anthropic-ai/claude-agent-sdk";
import { lockChecks } from "../src/lock.js";

const stop: StopHookInput = { session_id: "s1", transcript_path: "/tmp/t.jsonl", cwd: "/tmp", hook_event_name: "Stop", stop_hook_active: false };
const signal = new AbortController().signal;

test("a test file rewritten by any tool blocks the stop", async () => {
  const dir = await mkdtemp(join(tmpdir(), "checks-"));
  await writeFile(join(dir, "cart.test.ts"), "expect(screen.getByText('No projects yet'))");
  const hook = lockChecks(dir);
  assert.deepEqual(await hook(stop, undefined, { signal }), {});
  await writeFile(join(dir, "cart.test.ts"), "expect(screen.getByText('Loading'))");
  assert.equal(((await hook(stop, undefined, { signal })) as { decision?: string }).decision, "block");
});
